const choice = String(inputs.modeChoice || 'auto');
const material = String(inputs.material || '').trim();
const hasMaterial = material.length > 0 || Boolean(inputs.digest && inputs.digest.hasMaterial);
let mode;
if (choice === 'fiction') mode = 'fiction';
else if (choice === 'nonfiction') mode = 'nonfiction';
else mode = hasMaterial ? 'nonfiction' : 'fiction';
if (mode === 'nonfiction' && material.length === 0 && !(inputs.digest && inputs.digest.hasMaterial)) mode = 'fiction';
return { mode, hasMaterial };

