config.code:
const chapters = Array.isArray(inputs.chapters) ? inputs.chapters : [];
const title = (inputs.title || '').trim();
const body = chapters.map(function (c, i) {
  const text = c && c.content ? c.content : (typeof c === 'string' ? c : '');
  const head = (c && c.title) ? '## ' + c.title + '\n\n' : '';
  return (i > 0 ? '\n\n' : '') + head + text;
}).join('');
return (title ? title + '\n\n' : '') + body;

