const draft = String(inputs.draft || '');
const t = inputs.titles && typeof inputs.titles === 'object' ? inputs.titles : null;
let md = draft;
if (t && Array.isArray(t.options) && t.options.length) {
  const lines = t.options.map(function (o, i) { return (i + 1) + '. ' + String(o.title || '') + (o.why ? ('（' + o.why + '）') : ''); });
  const rec = t.recommended ? ('

推荐：' + String(t.recommended)) : '';
  md = md + '

---

## 备选标题方案

' + lines.join('
') + rec;
}
return { md };
